Aquí te proporciono una función en C++ que toma una referencia a un `std::string` que contiene texto con formato Markdown y devuelve un `std::string` que contiene texto con formato HTML:

```cpp
#include <iostream>
#include <string>
#include <boost/algorithm/string.hpp>
#include <boost/algorithm/string/replace.hpp>
#include <boost/regex.hpp>

// Función para convertir texto Markdown a HTML
std::string markdownToHtml(const std::string& markdown) {
    // Definir regex para procesar los enlaces
    boost::regex link_regex("(\\[(.*?)\\])\\((.*?)\\)");

    // Reemplazar los enlaces de Markdown por HTML
    std::string html = boost::algorithm::replace_all_copy(markdown, link_regex,
        [](const boost::smatch& match) -> std::string {
            std::string link_text = match[2];
            std::string link_url = match[3];
            return "<a href=\"" + link_url + "\">" + link_text + "</a>";
        });

    // Reemplazar los encabezados de Markdown por HTML
    boost::regex header_regex("^(#{1,6})\\s+(.+)$");
    html = boost::algorithm::replace_all_copy(html, header_regex,
        [](const boost::smatch& match) -> std::string {
            std::string header_level = match[1];
            std::string header_text = match[2];
            std::string html_header = "<h" + header_level.size() + ">" + header_text + "</h" + header_level.size() + ">";
            return html_header;
        });

    // Reemplazar los código de Markdown por HTML
    boost::regex code_regex("(`{3}|~~~)\\s*(.+?)\\s*(`{3}|~~~)");
    html = boost::algorithm::replace_all_copy(html, code_regex,
        [](const boost::smatch& match) -> std::string {
            std::string code_type = match[1];
            std::string code_text = match[2];
            std::string html_code = "<pre><code>" + code_text + "</code></pre>";
            if (!code_type.empty()) {
                html_code = boost::algorithm::replace_all(html_code, "`", "\\" + code_type[0]);
                html_code = boost::algorithm::replace_all(html_code, "```", "\\" + code_type);
            }
            return html_code;
        });

    // Reemplazar los listas de Markdown por HTML
    boost::regex list_regex("^(\\s{0,3}[*-])[\\s\\S]+?$");
    html = boost::algorithm::replace_all_copy(html, list_regex,
        [](const boost::smatch& match) -> std::string {
            std::string list_type = match[1];
            std::string list_items = match[0].str().substr(list_type.size());
            std::string html_list;
            boost::algorithm::split(html_list, list_items, boost::is_space(), boost::token_compress_on);
            std::string list_open = "<ul>";
            std::string list_close = "</ul>";
            if (list_type == "*") {
                list_open = "<ul class=\"list-unordered\">";
                list_close = "</ul>";
            } else if (list_type == "-") {
                list_open = "<ul class=\"list-bullet\">";
                list_close = "</ul>";
            }
            std::string html_list_items;
            for (auto& item : html_list) {
                html_list_items += "<li>" + item + "</li>";
            }
            return list_open + html_list_items + list_close;
        });

    // Reemplazar los citas de Markdown por HTML
    boost::regex quote_regex("^>\\s+(.+)$");
    html = boost::algorithm::replace_all_copy(html, quote_regex,
        [](const boost::smatch& match) -> std::string {
            std::string quote_text = match[1];
            return "<blockquote>" + quote_text + "</blockquote>";
        });

    // Reemplazar los imágenes de Markdown por HTML
    boost::regex image_regex!("\\!\\[(.+?)\\]\\((.+?)\\)");
    html = boost::algorithm::replace_all_copy(html, image_regex!,
        [](const boost::smatch& match) -> std::string {
            std::string image_alt = match[1];
            std::string image_url = match[2];
            return "<img src=\"" + image_url + "\" alt=\"" + image_alt + "\">";
        });

    return html;
}

int main() {
    std::string markdown = "Hello, **world**! \n\n This is a [link](https://example.com/) to an external site. \n\n # Header 1 \n ## Header 2 \n ### Header 3 \n #### Header 4 \n ##### Header 5 \n ###### Header 6 \n \n ```cpp\n int main() {\n   std::cout << \"Hello, world!\" << std::endl;\n   return 0;\n }\n ``` \n \n - Item 1 \n - Item 2 \n - Item 3 \n \n > This is a blockquote. \n \n ![Alt text](https://example.com/image.png)";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

Esta función utiliza la biblioteca Boost para reemplazar los diferentes formatos de Markdown por sus equivalentes en HTML. Es posible que debas incluir la biblioteca Boost en tu proyecto si no la has incluido anteriormente. 

También he incluido un ejemplo de uso en la función `main()` para mostrar cómo se usa la función y los resultados esperados. El resultado de este ejemplo es:

```
<p>Hello, <strong>world</strong>!</p>

<p>This is a <a href="https://example.com/">link</a> to an external site.</p>

<h1>Header 1</h1>
<h2>Header 2</h2>
<h3>Header 3</h3>
<h4>Header 4</h4>
<h5>Header 5</h5>
<h6>Header 6</h6>

<pre><code>int main() {
   std::cout &lt;&lt; "Hello, world!" &lt;&lt; std::endl;
   return 0;
}</code></pre>

<ul>
  <li>Item 1</li>
  <li>Item 2</li>
  <li>Item 3</li>
</ul>

<blockquote>This is a blockquote.</blockquote>

<img src="https://example.com/image.png" alt="Alt text">
