```c++
#include <iostream>

using namespace std;

int main() {
    int m1Rows, m1Cols, m2Rows, m2Cols;
    cout << "Enter the number of rows and columns for the first matrix: ";
    cin >> m1Rows >> m1Cols;

    int **matrix1 = new int *[m1Rows];
    for (int I = 0; I < m1Rows; i++) {
        matrix1[i] = new int[m1Cols];
    }

    cout << "Enter the elements of the first matrix:" << endl;
    for (int I = 0; I < m1Rows; i++) {
        for (int j = 0; j < m1Cols; j++) {
            cin >> matrix1[i][j];
        }
    }

    cout << "Enter the number of rows and columns for the second matrix: ";
    cin >> m2Rows >> m2Cols;

    int **matrix2 = new int *[m2Rows];
    for (int I = 0; I < m2Rows; i++) {
        matrix2[i] = new int[m2Cols];
    }

    cout << "Enter the elements of the second matrix:" << endl;
    for (int I = 0; I < m2Rows; i++) {
        for (int j = 0; j < m2Cols; j++) {
            cin >> matrix2[i][j];
        }
    }

    int commonElements = 0;

    // Compare each element of matrix1 with all elements of matrix2
    for (int I = 0; I < m1Rows; i++) {
        for (int j = 0; j < m1Cols; j++) {
            for (int k = 0; k < m2Rows; k++) {
                if (matrix1[i][j] == matrix2[k][j]) {
                    commonElements++;
                    break;
                }
            }
        }
    }

    cout << "The number of common elements in the matrices is: " << commonElements << endl;

    // Free memory allocated for matrices
    for (int I = 0; I < m1Rows; i++) {
        delete[] matrix1[i];
    }
